"""Run all 16 Python 3.11 core examples in isolated namespaces."""

SNIPPETS = ['ready = True\nif ready:\n    state = "online"\nassert state == "online"', 'temperature = 24.5\nline = f"temperature={temperature:.1f}"\nwire = line.encode("utf-8")\nassert wire.decode("utf-8") == "temperature=24.5"', 'from copy import deepcopy\noriginal = {"points": [1]}\nalias, shallow, deep = original, original.copy(), deepcopy(original)\nalias["points"].append(2)\nassert shallow["points"] == [1, 2] and deep["points"] == [1]', 'value = 24\nenabled = True\nassert enabled and (18 <= value < 30)\nassert (2 + 3 * 4, (2 + 3) * 4, -7 // 3) == (14, 20, -3)\nassert (None is None) and (0 or "default") == "default"', 'batches = [[1, 2], [2, 3]]\nflat = [value for batch in batches for value in batch]\nfirst, *middle, last = flat\nassert (first, middle, last) == (1, [2, 2], 3)\nassert flat[::2] == [1, 2] and set(flat) == {1, 2, 3}\nassert {str(i): i*i for i in range(3)}["2"] == 4', 'def classify(message):\n    match message:\n        case {"kind": "alarm", "value": n} if n > 30:\n            return "alarm"\n        case _:\n            return "normal"\nfor value in [20, 24]:\n    if value > 30:\n        break\nelse:\n    assert classify({"kind": "alarm", "value": 35}) == "alarm"', 'def metric(name, /, *samples, unit="C", **tags):\n    return name, sum(samples), unit, tags\nassert metric("T10", 20, 4, unit="C", zone="A") == (\n    "T10", 24, "C", {"zone": "A"}\n)', 'from functools import wraps\ndef with_offset(offset):\n    def decorate(fn):\n        @wraps(fn)\n        def measured(value):\n            return fn(value) + offset\n        return measured\n    return decorate\n@with_offset(2)\ndef read(value):\n    return value\nassert read(20) == 22 and read.__name__ == "read"', 'from dataclasses import dataclass\n@dataclass(frozen=True, slots=True)\nclass Series:\n    values: tuple[float, ...]\n    def __len__(self):\n        return len(self.values)\nassert len(Series((20.0, 21.0))) == 2', 'def points():\n    yield "T10"\n    yield from ["T11", "T12"]\nit = iter(points())\nassert next(it) == "T10"\nassert list(it) == ["T11", "T12"] and list(it) == []', 'try:\n    try:\n        int("bad")\n    except ValueError as cause:\n        raise RuntimeError("invalid reading") from cause\nexcept RuntimeError as error:\n    assert isinstance(error.__cause__, ValueError)\nhandled = []\ntry:\n    raise ExceptionGroup("batch", [ValueError("input"), OSError("I/O")])\nexcept* ValueError as group:\n    handled.append(len(group.exceptions))\nexcept* OSError as group:\n    handled.append(len(group.exceptions))\nassert handled == [1, 1]', 'from contextlib import contextmanager\nevents = []\n@contextmanager\ndef reading_session():\n    events.append("open")\n    try:\n        yield "T10"\n    finally:\n        events.append("close")\ntry:\n    with reading_session() as sensor:\n        assert sensor == "T10"\n        raise ValueError("demo")\nexcept ValueError:\n    pass\nassert events == ["open", "close"]', 'from typing import NotRequired, Self, TypedDict\nclass Point(TypedDict):\n    name: str\n    quality: NotRequired[str]\nclass Recorder:\n    def add(self, point: Point) -> Self:\n        self.last = point\n        return self\nassert Recorder().add({"name": "T10"}).last["name"] == "T10"', 'import importlib\nimport sys\ndef main():\n    return importlib.import_module("math").sqrt(81)\nif __name__ == "__main__":\n    assert main() == 9\n    assert sys.version_info >= (3, 11)', 'import json\nfrom pathlib import Path\nfrom tempfile import TemporaryDirectory\nwith TemporaryDirectory() as tmp:\n    path = Path(tmp) / "report.json"\n    path.write_text(json.dumps({"value": 24.5}, allow_nan=False), encoding="utf-8")\n    assert json.loads(path.read_text(encoding="utf-8")) == {"value": 24.5}', 'import asyncio\nasync def read(name):\n    await asyncio.sleep(0)\n    return name\nasync def batch():\n    async with asyncio.TaskGroup() as group:\n        tasks = [group.create_task(read(name)) for name in ("T10", "T11")]\n    return [task.result() for task in tasks]\nassert asyncio.run(batch()) == ["T10", "T11"]']

if __name__ == "__main__":
    for idx, code in enumerate(SNIPPETS, 1):
        exec(compile(code, f"C{idx:02}", "exec"), {"__name__": "__main__"})
    print("16 core examples passed")
